#include <nuttx/config.h>
#include <arch/irq.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* RISC-V 基础中断数 */

#define RISCV_NIRQ_INTERRUPTS    16

/* D13x 外设中断号 */

#define D13X_IRQ_UART0           76
#define D13X_IRQ_GPIO            77
#define D13X_IRQ_SPI0            78
#define D13X_IRQ_I2C0            79
#define D13X_IRQ_TIMER0          80

/* 总中断数 */

#define NR_IRQS                  (D13X_IRQ_TIMER0 + 1)

/* 中断优先级 */

#define D13X_IRQ_PRIORITY_LOW    0
#define D13X_IRQ_PRIORITY_HIGH   15

#endif /* __VENDOR_ARTINCHIP_CHIPS_D13X_INCLUDE_IRQ_H */

