 ****************************************************************************/

/****************************************************************************
 * Name: artinchip_serialinit
 *
 * Description:
 *   Register serial console and serial ports
 *
 ****************************************************************************/

void artinchip_serialinit(void)
{
  uart_register("/dev/console", &g_d13x_uart0);
}

