/****************************************************************************
 * vendor/artinchip/chips/d13x/artinchip_oneshot.c
 *
 * D13x 定时器驱动（arch_alarm 模型）
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/timers/oneshot.h>
#include <nuttx/irq.h>
#include "chip.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* GTC（通用计时器）基地址（需查阅 D13x 用户手册确认） */

#define D13X_GTC_BASE          0x18040000
#define D13X_GTC_CFG           (D13X_GTC_BASE + 0x0000)
#define D13X_GTC_CTRL          (D13X_GTC_BASE + 0x0004)
#define D13X_GTC_CNT           (D13X_GTC_BASE + 0x0008)
#define D13X_GTC_CMP           (D13X_GTC_BASE + 0x000C)
#define D13X_GTC_INT           (D13X_GTC_BASE + 0x0010)

/* GTC 中断号 */

#define D13X_IRQ_GTC           80

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct d13x_oneshot_lowerhalf_s
{
  struct oneshot_lowerhalf_s lower;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct d13x_oneshot_lowerhalf_s g_d13x_oneshot;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static inline void writel(uint32_t val, uint32_t addr)
{
  *(volatile uint32_t *)addr = val;
}

static inline uint32_t readl(uint32_t addr)
{
  return *(volatile uint32_t *)addr;
}

/****************************************************************************
 * Name: d13x_oneshot_current
 *
 * Description:
 *   Get the current timer value
 *
 ****************************************************************************/

static clkcnt_t d13x_oneshot_current(struct oneshot_lowerhalf_s *lower)
{
  return (clkcnt_t)readl(D13X_GTC_CNT);
}

/****************************************************************************
 * Name: d13x_oneshot_start
 *
 * Description:
 *   Start the oneshot timer with a relative timeout
 *
 ****************************************************************************/

static void d13x_oneshot_start(struct oneshot_lowerhalf_s *lower,
                                clkcnt_t delta)
{
  uint32_t now = readl(D13X_GTC_CNT);
  uint32_t cmp = now + delta;

  writel(cmp, D13X_GTC_CMP);
  writel(1, D13X_GTC_INT);
}

/****************************************************************************
 * Name: d13x_oneshot_start_absolute
 *
 * Description:
 *   Start the oneshot timer with an absolute timeout
 *
 ****************************************************************************/

static void d13x_oneshot_start_absolute(struct oneshot_lowerhalf_s *lower,
                                         clkcnt_t expected)
{
  writel((uint32_t)expected, D13X_GTC_CMP);
  writel(1, D13X_GTC_INT);
}

/****************************************************************************
 * Name: d13x_oneshot_cancel
 *
 * Description:
 *   Cancel the oneshot timer
 *
 ****************************************************************************/

static void d13x_oneshot_cancel(struct oneshot_lowerhalf_s *lower)
{
  writel(0, D13X_GTC_INT);
}

/****************************************************************************
 * Name: d13x_oneshot_maxdelay
 *
 * Description:
 *   Get the maximum delay value
 *
 ****************************************************************************/

static clkcnt_t d13x_oneshot_maxdelay(struct oneshot_lowerhalf_s *lower)
{
  return 0xFFFFFFFF;
}

/****************************************************************************
 * Name: d13x_oneshot_handler
 *
 * Description:
 *   Timer interrupt handler
 *
 ****************************************************************************/

static int d13x_oneshot_handler(int irq, FAR void *context, FAR void *arg)
{
  struct oneshot_lowerhalf_s *lower = arg;

  /* 清除中断 */

  writel(0, D13X_GTC_INT);

  /* 调用上层回调 */

  if (lower->ops->current)
    {
      lower->ops->callback(lower, lower->ops->current(lower));
    }

  return OK;
}

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct oneshot_operations_s g_d13x_oneshot_ops =
{
  .current        = d13x_oneshot_current,
  .start          = d13x_oneshot_start,
  .start_absolute = d13x_oneshot_start_absolute,
  .cancel         = d13x_oneshot_cancel,
  .max_delay      = d13x_oneshot_maxdelay,
};

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: up_timer_initialize
 *
 * Description:
 *   This function is called during start-up to initialize the timer
 *   interrupt.
 *
 ****************************************************************************/

void up_timer_initialize(void)
{
  /* 初始化 GTC 定时器 */

  writel(0, D13X_GTC_INT);
  writel(1, D13X_GTC_CTRL);

  /* 绑定中断处理函数 */

  irq_attach(D13X_IRQ_GTC, d13x_oneshot_handler, &g_d13x_oneshot.lower);
  up_enable_irq(D13X_IRQ_GTC);

  /* 创建 oneshot 实例并绑定系统定时器 */

  g_d13x_oneshot.lower.ops = &g_d13x_oneshot_ops;
  up_alarm_set_lowerhalf(&g_d13x_oneshot.lower);
}

