static int d13x_uart0_handler(int irq, FAR void *context, FAR void *arg)
{
  FAR struct uart_dev_s *dev = arg;

  /* 读取中断状态 */

  uint32_t ier = getreg32(D13X_UART0_BASE + UART_DLH);

  /* 处理接收中断 */

  if (ier & 0x01)
    {
      /* 接收数据并放入缓冲区 */

      while (getreg32(D13X_UART0_BASE + UART_LSR) & UART_LSR_DR)
        {
          uint8_t ch = getreg32(D13X_UART0_BASE + UART_RBR_THR_DLL) & 0xFF;
          uart_recvchar(dev, ch);
        }
    }

  return OK;
}

static int d13x_uart_setup(FAR struct uart_dev_s *dev)

