/****************************************************************************
 * D13x Bootloader - linker.ld
 *
 * D13x bootloader 链接脚本
 *
 ****************************************************************************/

/* 入口点 */

ENTRY(_start)

/* 内存布局 */

MEMORY
{
  sram (rwx) : ORIGIN = 0x20000000, LENGTH = 1M
  psram (rwx) : ORIGIN = 0x30000000, LENGTH = 8M
}

/* 段定义 */

SECTIONS
{
  /* 代码段 */

  .text : {
    _stext = .;
    *(.text.startup)
    *(.text .text.*)
    _etext = .;
  } > sram

  /* 只读数据段 */

  .rodata : {
    _srodata = .;
    *(.rodata .rodata.*)
    _erodata = .;
  } > sram

  /* 已初始化数据段 */

  .data : {
    _sdata = .;
    *(.data .data.*)
    _edata = .;
  } > sram AT > sram

  /* 未初始化数据段 */

  .bss : {
    _sbss = .;
    *(.bss .bss.*)
    *(COMMON)
    . = ALIGN(4);
    _ebss = .;
  } > sram

  /* 堆栈 */

  .stack (NOLOAD) : {
    . = ALIGN(8);
    . = . + 4096;
    _estack = .;
  } > sram
}

#include <stdint.h>

#define getreg32(a)     (*(volatile uint32_t *)(a))
#define putreg32(v,a)   (*(volatile uint32_t *)(a) = (v))

void d13x_clock_init(void)
{
  uint32_t reg;

  reg = getreg32(0x180200A4);
  reg |= (1 << 1);
  putreg32(reg, 0x180200A4);

  reg = getreg32(0x180200A0);
  reg |= (1 << 31) | (1 << 0);
  putreg32(reg, 0x180200A0);

  putreg32(0x240C4040, 0x18020044);
  while (!(getreg32(0x18020044) & (1 << 17)));

  putreg32(0x240C4040, 0x18020040);
  while (!(getreg32(0x18020040) & (1 << 17)));

  putreg32(0x00000001, 0x18020100);
  putreg32(0x00000001, 0x18020120);
  putreg32(0x00000100, 0x18020200);

  reg = getreg32(0x1802083C);
  reg |= (1 << 12) | (1 << 13);
  putreg32(reg, 0x1802083C);
  putreg32(0x00001001, 0x18020840);
}

void d13x_uart_init(void)
{
  uint32_t divisor = 60000000 / (16 * 115200);
  putreg32(0, 0x1871000C);
  putreg32(divisor & 0xFF, 0x18710000);
  putreg32((divisor >> 8) & 0xFF, 0x18710004);
  putreg32(0x07, 0x18710008);
  putreg32(0x03, 0x1871000C);
}

void d13x_putc(char ch)
{
  while (!(getreg32(0x18710014) & (1 << 5)));
  putreg32((uint32_t)ch, 0x18710000);
}

int d13x_getc(void)
{
  while (!(getreg32(0x18710014) & (1 << 0)));
  return (int)(getreg32(0x18710000) & 0xFF);
}

int d13x_uart_rxready(void)
{
  return (getreg32(0x18710014) & (1 << 0)) != 0;
}

#include <stdint.h>

extern void d13x_clock_init(void);
extern void d13x_uart_init(void);
extern void d13x_putc(char ch);
extern int d13x_getc(void);
extern int d13x_uart_rxready(void);

static void print_str(const char *str)
{
  while (*str)
  {
    d13x_putc(*str++);
  }
}

int main(void)
{
  d13x_clock_init();
  d13x_uart_init();

  print_str("\r\nD13x Bootloader v1.0\r\n");
  print_str("Waiting for USB command...\r\n");

  while (1)
  {
    if (d13x_uart_rxready())
    {
      int ch = d13x_getc();
      d13x_putc(ch);
      if (ch == '\r' || ch == '\n')
      {
        d13x_putc('\r');
        d13x_putc('\n');
      }
    }
  }

  return 0;
}

