{
  putreg32(0x00000002, SPI_EN);
  putreg32(0x00000000, SPI_CLKR);
  putreg32(0x00000001, SPI_SER);
}

static void d13x_spi_cs(int assert)
{
  putreg32(assert ? 0x00000001 : 0x00000000, SPI_CER);
}

static void d13x_spi_txrx(uint8_t *tx, uint8_t *rx, int len)
{
