/****************************************************************************
 * D13x tinySPL Bootloader - system.c
 *
 * 完整的系统初始化：时钟、UART、SPI Flash
 *
 ****************************************************************************/

#include <stdint.h>
#include "d13x_boot.h"

/****************************************************************************
 * 寄存器访问宏
 ****************************************************************************/

#define getreg32(a)     (*(volatile uint32_t *)(a))
#define putreg32(v,a)   (*(volatile uint32_t *)(a) = (v))

/****************************************************************************
 * 时钟系统 (CMU)
 ****************************************************************************/

static void d13x_clock_init(void)
{
  uint32_t reg;

  /* 打开 24MHz 振荡器 */

  reg = getreg32(0x180200A4);
  reg |= (1 << 1);
  putreg32(reg, 0x180200A4);

  /* PLL 公共电路 LDO */

  reg = getreg32(0x180200A0);
  reg |= (1 << 31) | (1 << 0);
  putreg32(reg, 0x180200A0);

  /* PLL_INT1 → 1.2GHz */

  putreg32(0x240C4040, 0x18020044);
  while (!(getreg32(0x18020044) & (1 << 17)));

  /* PLL_INT0 → 480MHz */

  putreg32(0x240C4040, 0x18020040);
  while (!(getreg32(0x18020040) & (1 << 17)));

  /* 总线时钟 */

  putreg32(0x00000001, 0x18020100);
  putreg32(0x00000001, 0x18020120);
  putreg32(0x00000100, 0x18020200);

  /* GPIO/UART 时钟 */

  reg = getreg32(0x1802083C);
  reg |= (1 << 12) | (1 << 13);
  putreg32(reg, 0x1802083C);
  putreg32(0x00001001, 0x18020840);
}

/****************************************************************************
 * UART 驱动
 ****************************************************************************/

void d13x_uart_init(void)
{
  uint32_t divisor = 60000000 / (16 * 115200);
  putreg32(0, 0x1871000C);
  putreg32(divisor & 0xFF, 0x18710000);
  putreg32((divisor >> 8) & 0xFF, 0x18710004);
  putreg32(0x07, 0x18710008);
  putreg32(0x03, 0x1871000C);
}

void d13x_putc(char ch)
{
  while (!(getreg32(0x18710014) & (1 << 5)));
  putreg32((uint32_t)ch, 0x18710000);
}

int d13x_getc(void)
{
  while (!(getreg32(0x18710014) & (1 << 0)));
  return (int)(getreg32(0x18710000) & 0xFF);
}

int d13x_uart_rxready(void)
{
  return (getreg32(0x18710014) & (1 << 0)) != 0;
}

/****************************************************************************
 * SPI 控制器
 ****************************************************************************/

#define SPI0_BASE       0x18600000
#define SPI_TXD         (SPI0_BASE + 0x00)
#define SPI_RXD         (SPI0_BASE + 0x04)
#define SPI_CLKR        (SPI0_BASE + 0x08)
#define SPI_CER         (SPI0_BASE + 0x0C)
#define SPI_SER         (SPI0_BASE + 0x10)
#define SPI_SR          (SPI0_BASE + 0x28)
#define SPI_EN          (SPI0_BASE + 0x88)
#define SPI_CFG1        (SPI0_BASE + 0x80)

static void d13x_spi_init(void)
{
  putreg32(0x00000002, SPI_EN);
  putreg32(0x00000000, SPI_CLKR);
  putreg32(0x00000001, SPI_SER);
}

static void d13x_spi_cs(int assert)
{
  putreg32(assert ? 0x00000001 : 0x00000000, SPI_CER);
}

static void d13x_spi_txrx(uint8_t *tx, uint8_t *rx, int len)
{
  int i;
  for (i = 0; i < len; i++)
  {
    putreg32(tx ? tx[i] : 0, SPI_TXD);
    while (getreg32(SPI_SR) & (1 << 0));
    if (rx) rx[i] = (uint8_t)getreg32(SPI_RXD);
  }
}

/****************************************************************************
 * SPI NOR Flash 驱动
 ****************************************************************************/

#define FLASH_WRITE_ENABLE    0x06
#define FLASH_READ_STATUS     0x05
#define FLASH_PAGE_PROGRAM    0x02
#define FLASH_SECTOR_ERASE    0x20
#define FLASH_READ_ID         0x9F

static void d13x_flash_write_enable(void)
{
  uint8_t cmd = FLASH_WRITE_ENABLE;
  d13x_spi_cs(1);
  d13x_spi_txrx(&cmd, 0, 1);
  d13x_spi_cs(0);
}

static void d13x_flash_wait_busy(void)
{
  uint8_t cmd = FLASH_READ_STATUS;
  uint8_t status;
  do {
    d13x_spi_cs(1);
    d13x_spi_txrx(&cmd, 0, 1);
    d13x_spi_txrx(0, &status, 1);
    d13x_spi_cs(0);
  } while (status & 0x01);
}

void d13x_flash_write(uint32_t addr, uint8_t *data, int len)
{
  uint8_t cmd[4];
  cmd[0] = FLASH_PAGE_PROGRAM;
  cmd[1] = (addr >> 16) & 0xFF;
  cmd[2] = (addr >> 8) & 0xFF;
  cmd[3] = addr & 0xFF;

  d13x_flash_write_enable();
  d13x_spi_cs(1);
  d13x_spi_txrx(cmd, 0, 4);
  d13x_spi_txrx(data, 0, len);
  d13x_spi_cs(0);
  d13x_flash_wait_busy();
}

void d13x_flash_erase_sector(uint32_t addr)
{
  uint8_t cmd[4];
  cmd[0] = FLASH_SECTOR_ERASE;
  cmd[1] = (addr >> 16) & 0xFF;
  cmd[2] = (addr >> 8) & 0xFF;
  cmd[3] = addr & 0xFF;

  d13x_flash_write_enable();
  d13x_spi_cs(1);
  d13x_spi_txrx(cmd, 0, 4);
  d13x_spi_cs(0);
  d13x_flash_wait_busy();
}

uint32_t d13x_flash_read_id(void)
{
  uint8_t cmd = FLASH_READ_ID;
  uint8_t id[3];
  uint32_t result;

  d13x_spi_cs(1);
  d13x_spi_txrx(&cmd, 0, 1);
  d13x_spi_txrx(0, id, 3);
  d13x_spi_cs(0);

  result = (id[0] << 16) | (id[1] << 8) | id[2];
  return result;
}

void d13x_flash_init(void)
{
  d13x_spi_init();
}

/****************************************************************************
 * D13x tinySPL Bootloader - main.c
 *
 * 完整的 bootloader：接收固件并通过 SPI Flash 写入
 *
 ****************************************************************************/

#include <stdint.h>
#include <string.h>
#include "d13x_boot.h"

/****************************************************************************
 * 常量定义
 ****************************************************************************/

#define OS_LOAD_ADDR    0x20000000
#define FLASH_BASE      0x00000000

/* USB 协议命令 */

#define CMD_WRITE       0x01
#define CMD_READ        0x02
#define CMD_ERASE       0x03
#define CMD_INFO        0x04
#define CMD_BOOT        0x05
#define CMD_ACK         0x06
#define CMD_NAK         0x07

/****************************************************************************
 * 外部符号
 ****************************************************************************/

extern void d13x_clock_init(void);
extern void d13x_uart_init(void);
extern void d13x_putc(char ch);
extern int d13x_getc(void);
extern int d13x_uart_rxready(void);
extern void d13x_flash_init(void);
extern void d13x_flash_write(uint32_t addr, uint8_t *data, int len);
extern void d13x_flash_erase_sector(uint32_t addr);

/****************************************************************************
 * 辅助函数
 ****************************************************************************/

static void print_str(const char *str)
{
  while (*str)
    d13x_putc(*str++);
}

static void print_hex(uint32_t val)
{
  int i;
  char buf[9];
  for (i = 7; i >= 0; i--)
  {
    int nibble = (val >> (i * 4)) & 0xF;
    buf[7 - i] = nibble < 10 ? '0' + nibble : 'A' + nibble - 10;
  }
  buf[8] = '\0';
  print_str("0x");
  print_str(buf);
}

static uint32_t recv_u32(void)
{
  uint32_t val = 0;
  int i;
  for (i = 0; i < 4; i++)
    val = (val << 8) | d13x_getc();
  return val;
}

static void send_u32(uint32_t val)
{
  int i;
  for (i = 3; i >= 0; i--)
    d13x_putc((val >> (i * 8)) & 0xFF);
}

static void send_ack(void)
{
  d13x_putc(CMD_ACK);
}

static void send_nak(void)
{
  d13x_putc(CMD_NAK);
}

/****************************************************************************
 * 主函数
 ****************************************************************************/

int main(void)
{
  /* 初始化硬件 */

  d13x_clock_init();
  d13x_uart_init();
  d13x_flash_init();

  /* 输出启动信息 */

  print_str("\r\nD13x tinySPL v2.0\r\n");
  print_str("Flash ID: ");
  print_hex(0);
  print_str("\r\n");

  /* 主循环：等待命令 */

  while (1)
  {
    if (!d13x_uart_rxready())
      continue;

    uint8_t cmd = d13x_getc();

    switch (cmd)
    {
      case CMD_WRITE:
      {
        uint32_t addr = recv_u32();
        uint32_t len = recv_u32();
        uint8_t buf[256];
        uint32_t remaining = len;
        uint32_t offset = 0;

        while (remaining > 0)
        {
          uint32_t chunk = remaining > 256 ? 256 : remaining;
          uint32_t i;
          for (i = 0; i < chunk; i++)
            buf[i] = d13x_getc();

          d13x_flash_erase_sector(addr + offset);
          d13x_flash_write(addr + offset, buf, chunk);

          offset += chunk;
          remaining -= chunk;
        }

        send_ack();
        break;
      }

      case CMD_READ:
      {
        uint32_t addr = recv_u32();
        uint32_t len = recv_u32();
        uint32_t i;

        for (i = 0; i < len; i++)
          d13x_putc(((volatile uint8_t *)addr)[i]);

        send_ack();
        break;
      }

      case CMD_INFO:
      {
        send_u32(0x20000000);  /* SRAM base */
        send_u32(0x30000000);  /* PSRAM base */
        send_u32(0x00000000);  /* Flash base */
        send_u32(16 * 1024 * 1024);  /* Flash size */
        send_ack();
        break;
      }

      case CMD_BOOT:
      {
        print_str("Booting...\r\n");
        send_ack();

        /* 跳转到 OS 入口 */
        void (*entry)(void) = (void (*)(void))OS_LOAD_ADDR;
        entry();
        break;
      }

      default:
        send_nak();
        break;
    }
  }

  return 0;
}

