def detect_changes(self) -> Tuple[set, set]:
    """检测文件变化，返回 (modified, new) 两个集合"""
    cached_paths = {d["rel_path"]: d for d in self.documents}
    modified = set()
    new = set()

    # 检查已有文件：删除或修改
    for rp, meta in cached_paths.items():
        p = PROJECT_ROOT / rp
        if not p.exists():
            modified.add(rp)
        elif abs(p.stat().st_mtime - meta["mtime"]) > 1:
            modified.add(rp)

    # 检查新文件
    current_paths = set()
    for dir_name in INDEX_DIRS:
        dir_path = PROJECT_ROOT / dir_name
        if not dir_path.exists():
            continue
        for item in dir_path.rglob("*"):
            if item.is_file() and self.should_index(item):
                rp = str(item.relative_to(PROJECT_ROOT))
                current_paths.add(rp)
                if rp not in cached_paths:
                    new.add(rp)

    return modified, new

